solution.code:
#include <stdio.h>

void order(int *low, int *high) {
    if (*low > *high) {
        int temp = *low;
        *low = *high;
        *high = temp;
    }
}

int main() {
    int a = 9, b = 4;
    order(&a, &b);
    printf("%d %d\n", a, b);
    return 0;
}
